{
  "name": "bingo-friends",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "build": "vite build",
    "test": "node --test tests/"
  },
  "dependencies": {
    "@fontsource-variable/fredoka": "^5.1.0",
    "@fontsource-variable/space-grotesk": "^5.1.0",
