              <label className="home-check">
                <input type="checkbox" checked={bigScreen} onChange={(e) => setBigScreen(e.target.checked)} />
                <span>{t('bigScreen')}</span>
              </label>
              <button type="submit" className="home-btn" disabled={!trimmed}>
